(28161, 'Luke 23:51', 'Luke', 23, 51, 'خو د هغوی د دې پرېکړې او دې کار سره جوړ نه ؤ او د خدای د پاچاهۍ په انتظار ؤ.', 'خو د هغوی د دې پرېکرې او دې کار سره جور نه و او د خدای د پاچاهی په انتظار و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_51.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28162, 'Luke 23:52', 'Luke', 23, 52, 'هغه پیلاتوس ته ورغی او د عیسی مړی یې ترې وغوښت.', 'هغه پیلاتوس ته ورغی او د عیسی مری یې ترې وغوشت.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28163, 'Luke 23:53', 'Luke', 23, 53, 'بیا هغه د صلیب څخه مړی راښکته کړ او د کتان په کفن کې یې تاو کړ او په ګټ کې کیندل شوي قبر کې یې کېښود چې د دې نه مخکې په کې څوک نه ؤ ښخ شوی.', 'بیا هغه د صلیب چخه مری راشکته کر او د کتان په کفن کې یې تاو کر او په ګت کې کیندل شوی قبر کې یې کېشود چې د دې نه مخکې په کې چوک نه و شخ شوی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_53.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28164, 'Luke 23:54', 'Luke', 23, 54, 'دا د جمعې ورځ وه، یعنې سبت ته د تیاري نیولو ورځ وه او د سبت ورځ پیل کېدله.', 'دا د جمعې ورج وه، یعنې سبت ته د تیاری نیولو ورج وه او د سبت ورج پیل کېدله.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_54.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28165, 'Luke 23:55', 'Luke', 23, 55, 'کومې ښځې چې د جلیل څخه د عیسی سره راغلې وې یوسف پسې روانې وې. هغوی قبر ولیده چې د عیسی مړی په کې څنګه ایښودل شوی ؤ.', 'کومې شجې چې د جلیل چخه د عیسی سره راغلې وې یوسف پسې روانې وې. هغوی قبر ولیده چې د عیسی مری په کې چنګه ایشودل شوی و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_55.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28166, 'Luke 23:56', 'Luke', 23, 56, 'بیا هغوی بېرته د اورشلیم ښار ته لاړې او د مړي دپاره یې خوشبویه مسالې او عطر تیار کړل او د شریعت د حکم له مخې یې د سبت په ورځ ارام وکړ.', 'بیا هغوی بېرته د اورشلیم شار ته لارې او د مری دپاره یې خوشبویه مسالې او عطر تیار کرل او د شریعت د حکم له مخې یې د سبت په ورج ارام وکر.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_23_56.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28167, 'Luke 14:1', 'Luke', 14, 1, 'د سبت په یوه ورځ عیسی د ډوډۍ خوړلو دپاره د فریسیانو د ډلې د یو مشر کور ته لاړ او هلته خلکو په ځیر هغه ته کتل.', 'د سبت په یوه ورج عیسی د دودی خورلو دپاره د فریسیانو د دلې د یو مشر کور ته لار او هلته خلکو په جیر هغه ته کتل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28168, 'Luke 14:2', 'Luke', 14, 2, 'هلته عیسی ته مخامخ یو سړی ولاړ ؤ چې د پړسوب په ناروغۍ اخته ؤ.', 'هلته عیسی ته مخامخ یو سری ولار و چې د پرسوب په ناروغی اخته و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28169, 'Luke 14:3', 'Luke', 14, 3, 'عیسی د شریعت د عالمانو او فریسیانو څخه پوښتنه وکړه: «ایا د سبت په ورځ د ناروغانو روغول روا دي که نه؟»', 'عیسی د شریعت د عالمانو او فریسیانو چخه پوشتنه وکره: «ایا د سبت په ورج د ناروغانو روغول روا دی که نه؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28170, 'Luke 14:4', 'Luke', 14, 4, 'خو هغوی غلي پاتې شول. نو عیسی هغه سړی له لاسه ونیوه، هغه یې روغ کړ او رخصت یې کړ.', 'خو هغوی غلی پاتې شول. نو عیسی هغه سری له لاسه ونیوه، هغه یې روغ کر او رخصت یې کر.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28171, 'Luke 14:5', 'Luke', 14, 5, 'بیا عیسی د هغوی څخه پوښتنه وکړه: «که چېرې د سبت په ورځ په تاسو کې د کوم چا زوی یا غویی په څاه کې ولویږي، نو ایا هغه به یې سمدلاسه راونه باسي؟»', 'بیا عیسی د هغوی چخه پوشتنه وکره: «که چېرې د سبت په ورج په تاسو کې د کوم چا زوی یا غویی په چاه کې ولویزی، نو ایا هغه به یې سمدلاسه راونه باسی؟»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28172, 'Luke 14:6', 'Luke', 14, 6, 'خو د هغوی سره د دې خبرې ځواب نه ؤ. عاجزي او مېلمه‌پالنه', 'خو د هغوی سره د دې خبرې جواب نه و. عاجزی او مېلمه‌پالنه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_6.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28173, 'Luke 14:7', 'Luke', 14, 7, 'کله چې عیسی ولیدل چې ځینو مېلمنو کوښښ کاوه د ځانونو دپاره تر ټولو لوړ ځایونه ونیسي، نو هغوی ته یې دا مثال راوړ:', 'کله چې عیسی ولیدل چې جینو مېلمنو کوشش کاوه د جانونو دپاره تر تولو لور جایونه ونیسی، نو هغوی ته یې دا مثال راور:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28174, 'Luke 14:8', 'Luke', 14, 8, '«کله چې څوک تاسو ته د واده د مېلمستیا دپاره بلنه درکړي نو د مجلس په سر کې مه کښېنئ، ځکه کېدای شي چې ستاسو څخه کوم بل ډېر مهم سړی رابلل شوی وي،', '«کله چې چوک تاسو ته د واده د مېلمستیا دپاره بلنه درکری نو د مجلس په سر کې مه کشېنی، جکه کېدای شی چې ستاسو چخه کوم بل دېر مهم سری رابلل شوی وی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28175, 'Luke 14:9', 'Luke', 14, 9, 'او ستاسو کوربه چې تاسو دواړه یې رابللي یئ راشي او درته ووایي: ‹خپل ځای دې سړي ته پرېږده.› نو بیا به وشرمېږې او مجبوره به شې چې تر ټولو وروستني ځای کې کښېنې.', 'او ستاسو کوربه چې تاسو دواره یې رابللی یی راشی او درته ووایی: ‹خپل جای دې سری ته پرېزده.› نو بیا به وشرمېزې او مجبوره به شې چې تر تولو وروستنی جای کې کشېنې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28176, 'Luke 14:10', 'Luke', 14, 10, 'خو کله چې د چا مېلمه شې، نو لاړ شه او تر ټولو وروستني ځای کې کښېنه، ترڅو کله چې کوربه راشي او درته ووایي: ‹ای زما ملګریه! پاس کښېنئ.› په دې به د نورو ټولو مېلمنو په مخکې ستا عزت وشي،', 'خو کله چې د چا مېلمه شې، نو لار شه او تر تولو وروستنی جای کې کشېنه، ترچو کله چې کوربه راشی او درته ووایی: ‹ای زما ملګریه! پاس کشېنی.› په دې به د نورو تولو مېلمنو په مخکې ستا عزت وشی،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28177, 'Luke 14:11', 'Luke', 14, 11, 'ځکه څوک چې خپل ځان لوی ګڼي، هغه به خوار شي او څوک چې خپل ځان عاجز کړي، هغه به سرلوړی شي.»', 'جکه چوک چې خپل جان لوی ګنی، هغه به خوار شی او چوک چې خپل جان عاجز کری، هغه به سرلوری شی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28178, 'Luke 14:12', 'Luke', 14, 12, 'بیا عیسی خپل کوربه ته وویل: «کله چې د غرمې یا د ماښام ډوډۍ دپاره څوک راغواړې، نو خپلو ملګرو یا خپلو ورونو یا خپلوانو یا خپلو شتمنو ګاونډیانو ته بلنه مه ورکوه، ځکه چې هغوی به هم بېرته تاته بلنه درکړي او په دې ډول به ستا بدل پوره کړي.', 'بیا عیسی خپل کوربه ته وویل: «کله چې د غرمې یا د ماشام دودی دپاره چوک راغوارې، نو خپلو ملګرو یا خپلو ورونو یا خپلوانو یا خپلو شتمنو ګاوندیانو ته بلنه مه ورکوه، جکه چې هغوی به هم بېرته تاته بلنه درکری او په دې دول به ستا بدل پوره کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28179, 'Luke 14:13', 'Luke', 14, 13, 'خو کله چې مېلمستیا ورکوې، نو غریبانو، شلانو، ګوډانو او ړندو ته بلنه ورکړه.', 'خو کله چې مېلمستیا ورکوې، نو غریبانو، شلانو، ګودانو او رندو ته بلنه ورکره.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28180, 'Luke 14:14', 'Luke', 14, 14, 'نو ته به بختور یې، ځکه چې هغوی ستا بدل نه شي پوره کولای. خو د قیامت په ورځ به خدای تاته د نېکانو سره اجر درکړي.» د لویې مېلمستیا مثال (متي ۲۲‏:‌۱‌‏-‌۱۰)', 'نو ته به بختور یې، جکه چې هغوی ستا بدل نه شی پوره کولای. خو د قیامت په ورج به خدای تاته د نېکانو سره اجر درکری.» د لویې مېلمستیا مثال (متی ۲۲‏:‌۱‌‏-‌۱۰)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28181, 'Luke 14:15', 'Luke', 14, 15, 'کله چې د حاضرو خلکو څخه یو تن چې په دسترخوان ورسره ناست ؤ دا واورېدل، نو عیسی ته یې وویل: «بختور دي هغه خلک چې د خدای په پاچاهۍ کې به په مېلمستیا کې کښېني.»', 'کله چې د حاضرو خلکو چخه یو تن چې په دسترخوان ورسره ناست و دا واورېدل، نو عیسی ته یې وویل: «بختور دی هغه خلک چې د خدای په پاچاهی کې به په مېلمستیا کې کشېنی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28182, 'Luke 14:16', 'Luke', 14, 16, 'عیسی هغه ته وویل: «یو سړي یوه لویه مېلمستیا جوړه کړه او ډېر خلک یې راوبلل.', 'عیسی هغه ته وویل: «یو سری یوه لویه مېلمستیا جوره کره او دېر خلک یې راوبلل.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_16.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28183, 'Luke 14:17', 'Luke', 14, 17, 'کله چې د ډوډۍ وخت شو، نو خپل نوکر یې مېلمنو پسې ولېږه چې ورته ووایي: ‹راشئ، هرڅه تیار دي.›', 'کله چې د دودی وخت شو، نو خپل نوکر یې مېلمنو پسې ولېزه چې ورته ووایی: ‹راشی، هرچه تیار دی.›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28184, 'Luke 14:18', 'Luke', 14, 18, 'خو هغوی ټولو بهانې پیل کړې. لومړني وویل: ‹ما لږه ځمکه اخیستې ده، باید لاړ شم او هغه ووینم. مهرباني وکړه زما عذر ومنه.›', 'خو هغوی تولو بهانې پیل کرې. لومرنی وویل: ‹ما لزه جمکه اخیستې ده، باید لار شم او هغه ووینم. مهربانی وکره زما عذر ومنه.›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28185, 'Luke 14:19', 'Luke', 14, 19, 'بل وویل: ‹ما پنځه جوړې غویان اخیستي دي او روان یم چې هغه امتحان کړم، مهرباني وکړه زما عذر ومنه.›', 'بل وویل: ‹ما پنجه جورې غویان اخیستی دی او روان یم چې هغه امتحان کرم، مهربانی وکره زما عذر ومنه.›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28186, 'Luke 14:20', 'Luke', 14, 20, 'او بل یې وویل: ‹ما نوی واده کړی دی، نو له دې امله نه شم درتللی.›', 'او بل یې وویل: ‹ما نوی واده کری دی، نو له دې امله نه شم درتللی.›', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_14_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
