(28232, 'John 20:5', 'John', 20, 5, 'هغه قبر ته ورټیټ شو او دننه یې وکتل او کفن یې ولیده چې هلته پروت ؤ، خو قبر ته وردننه نه شو.', 'هغه قبر ته ورتیت شو او دننه یې وکتل او کفن یې ولیده چې هلته پروت و، خو قبر ته وردننه نه شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
