(28234, 'John 20:7', 'John', 20, 7, 'او هغه دستمال چې د عیسی د سر نه تاو ؤ، هغه د کفن سره نه ؤ، بلکې هغه په خپله قات شوی ؤ او په بل ځای کې پروت ؤ.', 'او هغه دستمال چې د عیسی د سر نه تاو و، هغه د کفن سره نه و، بلکې هغه په خپله قات شوی و او په بل جای کې پروت و.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28235, 'John 20:8', 'John', 20, 8, 'بیا هغه بل شاګرد چې مخکې قبر ته رسېدلی ؤ، هم قبر ته ورننوت او چې کله یې هغه ولیده، نو باور یې وکړ،', 'بیا هغه بل شاګرد چې مخکې قبر ته رسېدلی و، هم قبر ته ورننوت او چې کله یې هغه ولیده، نو باور یې وکر،', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28236, 'John 20:9', 'John', 20, 9, 'ځکه چې هغوی لا تر دې وخته پورې د خدای په کلام باندې پوه شوي نه وو چې ویلي یې وو چې عیسی باید د مړو نه بیا راژوندی شي.', 'جکه چې هغوی لا تر دې وخته پورې د خدای په کلام باندې پوه شوی نه وو چې ویلی یې وو چې عیسی باید د مرو نه بیا راژوندی شی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28237, 'John 20:10', 'John', 20, 10, 'نو بیا هغه دواړه شاګردان بېرته کور ته لاړل. عیسی مریم مجدلیې ته ښکاره کیږي (متي ۲۸‏:‌۹، ۱۰ او مرقوس ۱۶‏:‌۹‌‏-‌۱۱)', 'نو بیا هغه دواره شاګردان بېرته کور ته لارل. عیسی مریم مجدلیې ته شکاره کیزی (متی ۲۸‏:‌۹، ۱۰ او مرقوس ۱۶‏:‌۹‌‏-‌۱۱)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28238, 'John 20:11', 'John', 20, 11, 'خو مریم د قبر نه دباندې ولاړه وه او ژړل یې. هغې لا ژړل چې ټیټه شوه او دننه قبر ته یې وکتل', 'خو مریم د قبر نه دباندې ولاره وه او ژرل یې. هغې لا ژرل چې تیته شوه او دننه قبر ته یې وکتل', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28239, 'John 20:12', 'John', 20, 12, 'او دوه فرښتې یې په سپینو کالیو کې ولیدلې چې په هغه ځای کې چې د عیسی مړی پروت ؤ یوه یې سرته او بله یې پښو ته ناسته وه.', 'او دوه فرشتې یې په سپینو کالیو کې ولیدلې چې په هغه جای کې چې د عیسی مری پروت و یوه یې سرته او بله یې پشو ته ناسته وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28240, 'John 20:13', 'John', 20, 13, 'هغوی د هغې نه پوښتنه وکړه: «ای ښځې، ته ولې ژاړې؟» هغې ورته وویل: «ځکه چې هغوی زما د استاذ مړی وړی دی او زه نه پوهېږم چې چېرته یې اچولی دی.»', 'هغوی د هغې نه پوشتنه وکره: «ای شجې، ته ولې ژارې؟» هغې ورته وویل: «جکه چې هغوی زما د استاذ مری وری دی او زه نه پوهېزم چې چېرته یې اچولی دی.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28241, 'John 20:14', 'John', 20, 14, 'کله چې هغې دا خبره وکړه نو مخ یې راواړاوه او عیسی یې ولیده چې هلته ولاړ دی، خو هغې ونه پېژانده چې دا عیسی دی.', 'کله چې هغې دا خبره وکره نو مخ یې راواراوه او عیسی یې ولیده چې هلته ولار دی، خو هغې ونه پېژانده چې دا عیسی دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28242, 'John 20:15', 'John', 20, 15, 'عیسی هغې ته وویل: «ای خورې، ته ولې ژاړې؟ څوک لټوې؟» هغې دا ګومان وکړ چې ګوندې هغه باغوان دی نو ورته ویې ویل: «ښاغلیه، که چېرې تا د هغه مړی وړی وي نو ماته ووایه چې هغه دې په کوم ځای کې اچولی دی چې زه لاړه شم او هغه راپیدا کړم.»', 'عیسی هغې ته وویل: «ای خورې، ته ولې ژارې؟ چوک لتوې؟» هغې دا ګومان وکر چې ګوندې هغه باغوان دی نو ورته ویې ویل: «شاغلیه، که چېرې تا د هغه مری وری وی نو ماته ووایه چې هغه دې په کوم جای کې اچولی دی چې زه لاره شم او هغه راپیدا کرم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28243, 'John 20:16', 'John', 20, 16, 'عیسی هغې ته وویل: «مریمې!» مریم هغه ته مخ ورواړاوه او په آرامي ژبه کې یې ورته وویل: «ربوني!» چې معنی یې ده «استاذه!»', 'عیسی هغې ته وویل: «مریمې!» مریم هغه ته مخ ورواراوه او په ارامی ژبه کې یې ورته وویل: «ربونی!» چې معنی یې ده «استاذه!»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28244, 'John 20:17', 'John', 20, 17, 'عیسی هغې ته وویل: «ماته لاس مه راوړه، ځکه چې زه لا تر‌اوسه پلار ته نه یم تللی. خو زما ورونو یعنې زما شاګردانو ته ورشه او هغوی ته ووایه چې زه اوس خپل پلار ته چې ستاسو پلار هم دې او خپل خدای ته چې ستاسو خدای هم دی، پورته ورځم.»', 'عیسی هغې ته وویل: «ماته لاس مه راوره، جکه چې زه لا تر‌اوسه پلار ته نه یم تللی. خو زما ورونو یعنې زما شاګردانو ته ورشه او هغوی ته ووایه چې زه اوس خپل پلار ته چې ستاسو پلار هم دې او خپل خدای ته چې ستاسو خدای هم دی، پورته ورجم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28245, 'John 20:18', 'John', 20, 18, 'نو مریم مجدلیه لاړه او شاګردانو ته یې وویل چې ما عیسی لیدلی دی. بیا هغوی ته یې د هغه پیغام ورساوه. عیسی خپلو شاګردانو ته ځان ښکاره کوي (متي ۲۸‏:‌۱۶‌‏-‌۲۰ او مرقوس ۱۶‏:‌۱۴‌‏-‌۱۸ او لوقا ۲۴‏:‌۳۶‌‏-‌۴۹)', 'نو مریم مجدلیه لاره او شاګردانو ته یې وویل چې ما عیسی لیدلی دی. بیا هغوی ته یې د هغه پیغام ورساوه. عیسی خپلو شاګردانو ته جان شکاره کوی (متی ۲۸‏:‌۱۶‌‏-‌۲۰ او مرقوس ۱۶‏:‌۱۴‌‏-‌۱۸ او لوقا ۲۴‏:‌۳۶‌‏-‌۴۹)', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_18.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
(28246, 'John 20:19', 'John', 20, 19, 'د هماغې یکشنبې په ماښام کله چې شاګردان د یهودیانو د مشرانو له وېرې د تړلو دروازو شاته سره راټول شوي وو، عیسی راغی او د هغوی په منځ کې ودرېده او ویې ویل: «سلام دې وي په تاسو باندې!»', 'د هماغې یکشنبې په ماشام کله چې شاګردان د یهودیانو د مشرانو له وېرې د ترلو دروازو شاته سره راتول شوی وو، عیسی راغی او د هغوی په منج کې ودرېده او ویې ویل: «سلام دې وی په تاسو باندې!»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28247, 'John 20:20', 'John', 20, 20, 'کله چې هغه دا وویل، نو هغوی ته یې خپل لاسونه او خپل بغل وروښودل. کله چې شاګردانو خپل استاذ ولیده نو ډېر خوشحاله شول.', 'کله چې هغه دا وویل، نو هغوی ته یې خپل لاسونه او خپل بغل وروشودل. کله چې شاګردانو خپل استاذ ولیده نو دېر خوشحاله شول.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28248, 'John 20:21', 'John', 20, 21, 'عیسی یوځل بیا وویل: «سلام دې وي په تاسو باندې! لکه څنګه چې پلار زه رالېږلی یم نو همداسې زه هم تاسو لېږم.»', 'عیسی یوجل بیا وویل: «سلام دې وی په تاسو باندې! لکه چنګه چې پلار زه رالېزلی یم نو همداسې زه هم تاسو لېزم.»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28249, 'John 20:22', 'John', 20, 22, 'بیا یې په هغوی وپوکل او ویې ویل: «زما له خوا روح القدس قبول کړئ.', 'بیا یې په هغوی وپوکل او ویې ویل: «زما له خوا روح القدس قبول کری.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237834, 1761237834),
(28250, 'John 20:23', 'John', 20, 23, 'که چېرې تاسو د چا ګناهونه وبخښئ، نو هغوی به وبخښل شي. که تاسو هغوی ونه بخښئ نو هغوی به ونه بخښل شي.» عیسی او توما', 'که چېرې تاسو د چا ګناهونه وبخشی، نو هغوی به وبخشل شی. که تاسو هغوی ونه بخشی نو هغوی به ونه بخشل شی.» عیسی او توما', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/John_20_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237834, 1761237834),
